function step(ctx) {
  const swarms = ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b => b.shortType===0 && b.construction===0);
  const orders = swarms.filter(b => !Array.isArray(b.production) || b.production[0]!==5 || b.production[1]!==1 || b.production[2]!==2).slice(0,32).map(b => ({type:'production',building:{id:b.id,generation:b.generation},ratios:[5,1,2]}));
  return {output:{swarms:swarms.length,settingsQueued:orders.length},orders};
}

