let pending=false, done=false, lastOrderTick=-100000;
function step(ctx) {
 if(done) return {output:{status:'complete'}};
 const units=ctx.game.units({team:ctx.myTeam,limit:200});
 const workers=units.filter(u=>u.type===0).length;
 if(workers<16) return {output:{workers,threshold:16,status:'watching'}};
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:100}).filter(b=>b.shortType===0 && b.construction===0);
 if(!swarms.length) return {output:{workers,threshold:16,status:'threshold-met-no-active-swarm'}};
 const target=swarms.every(b=>Array.isArray(b.production) && b.production[0]===0 && b.production[1]===0 && b.production[2]>0);
 if(target) {
  done=true;
  if(pending) ctx.wakeAgent({key:'warrior-production-ready',reason:'The worker threshold is met and warrior-only swarm production is observed.',data:{tick:ctx.tick,workers,swarms:swarms.map(b=>({id:b.id,generation:b.generation,production:b.production}))}});
  return {output:{workers,status:'warrior-only-observed'}};
 }
 const orders=[];
 if(!pending || ctx.tick-lastOrderTick>=100) {
  for(const b of swarms.slice(0,32)) orders.push({type:'production',building:{id:b.id,generation:b.generation},ratios:[0,0,1]});
  pending=true; lastOrderTick=ctx.tick;
 }
 return {output:{workers,status:pending?'production-order-pending':'threshold-met'},orders};
}

